{"script": "#!/bin/bash

# Find log files created in the last 7 days
recent_logs=$(find log_files -type f -mtime -7);

# Initialize total sum
total=0;

# Process each log file
for file in $recent_logs; do
  # Extract server ID from filename
  server_id=$(echo "$file" | grep -oP 'log_server_\K[0-9]+');

  # Check if server ID is prime
  if [[ $server_id -gt 1 ]]; then
    is_prime=1;
    for ((i=2; i*i<=server_id; i++)); do
      if ((server_id % i == 0)); then
        is_prime=0;
        break;
      fi
    done;

    # If server ID is prime, sum the integers in the file
    if [[ $is_prime -eq 1 ]]; then
      # Use awk to sum the integers in the file
      total=$((total + $(awk '{s+=$1} END {print s}' "$file")));
    fi
  fi
done;

# Output the total sum
echo $total
"}

